# verify rule f: smallest multi-cell 8-connected component's bbox, both demos
def analyze(g,color):
    h,w=len(g),len(g[0]); seen=[[0]*w for _ in range(h)]; results=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==color and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=1; c=[]
                while stack:
                    a,b=stack.pop(); c.append((a,b))
                    for da in (-1,0,1):
                        for db in (-1,0,1):
                            x,y=a+da,b+db
                            if (da or db) and 0<=x<h and 0<=y<w and g[x][y]==color and not seen[x][y]:
                                seen[x][y]=1; stack.append((x,y))
                xs=[x for x,y in c]; ys=[y for x,y in c]
                hh=max(xs)-min(xs)+1; ww=max(ys)-min(ys)+1
                sub=[[0]*ww for _ in range(hh)]
                for x,y in c: sub[x-min(xs)][y-min(ys)]=color
                results.append(((hh,ww),sub,len(c)))
    return results
def f(g,color):
    res=analyze(g,color)
    # smallest by cell count among multi-cell comps
    best=min([s for s in res if s[2]>=4], key=lambda t:t[2])
    return best[1]
