def norm(sub):
    hh=len(sub); ww=len(sub[0]); best=None
    variants=[]
    cur=sub
    for r in range(hh):
        variants.append([row[:] for row in cur])
        cur=[list(row) for row in zip(*cur)][::-1]
    for v in variants:
        variants.append(v[::-1])
    def canon(s):
        import itertools
        cands=[]
        for flips in range(4):
            for rot in range(4):
                # rotate by flipping
                s2=s
                for _ in range(rot): s2=[list(r) for r in zip(*s2)][::-1]
            cands.append(tuple(map(tuple,s2)))
            s2=s
            s2=[row[::-1] for row in s2]
        return min(cands)
    return canon(min(variants,key=lambda v:min(map(min,v))))
