def load_from(t):
    G2={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G2 and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G2[k]=[[int(x) for x in r] for r in rows]
    return G2

